import numpy as np

class KappaCalculator:
    """
    This is a class as KappaCalculator, supporting to calculate Cohen's and Fleiss' kappa coefficient.
    """

    @staticmethod
    def fleiss_kappa(testData, N, k, n):
        """
        Calculate Fleiss' kappa coefficient for a given matrix
        :param testData: The k-dimensional matrix that needs to calculate the Fleiss' kappa coefficient
        :param N: int, the total number of ratings
        :param k: int, Matrix dimension
        :param n: int, the number of raters
        :return:float, the Fleiss' kappa coefficient of the matrix
        """
        # Calculate the observed agreement matrix
        observed_agreement = np.zeros((k, k))
        for i in range(N):
            for j in range(i+1, N):
                for l in range(k):
                    if testData[i][l]!= testData[j][l]:
                        observed_agreement[testData[i][l]][testData[j][l]] += 1

        # Calculate the expected agreement matrix
        expected_agreement = np.zeros((k, k))
        for i in range(k):
            for j in range(k):
                expected_agreement[i][j] = (N * (N - 1)) / (n * (n - 1))

        # Calculate the Fleiss' kappa coefficient
        kappa = 1.0
        for i in range(k):
            for j in range(k):
                if expected_agreement[i][j]!= 0:
                    kappa -= (observed_agreement[i][j] - expected_agreement[i][j]) ** 2 / expected_agreement[i][j]

        return kappa

    def kappa(testData, k):
        """
        Calculate the cohens kappa value of a k-dimensional matrix
        :param testData: The k-dimensional matrix that needs to calculate the cohens kappa value
        :param k: int, Matrix dimension
        :return:float, the cohens kappa value of the matrix
        """
        N = len(testData)
        n = len(testData[0])

        # Calculate the observed agreement matrix
        observed_agreement = np.zeros((k, k))
        for i in range(N):
            for j in range(i+1, N):
                for l in range(k):
                    if testData[i][l]!= testData[j][l]:
                        observed_agreement[testData[i][l]][testData[j][l]] += 1

        # Calculate the expected agreement matrix
        expected_agreement = np.zeros((k, k))
        for i in range(k):
            for j in range(k):
                expected_agreement[i][j] = (N * (N - 1)) / (n * (n - 1))

        # Calculate the cohens kappa coefficient
        kappa = 1.0
        for i in range(k):
            for j in range(k):
                if expected_agreement[i][j]!= 0:
                    kappa -= (observed_agreement[i][j] - expected_agreement[i][j]) ** 2 / (expected_agreement[i][j] * (1 - expected_agreement[i][j]))

        return kappa
