            x1, y1, x2, y2 = x2, y2, x1, y1
        # check if there is an icon in the way
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            x, y = x1 + dx, y1 + dy
            while 0 <= x < self.BOARD_SIZE[0] and 0 <= y < self.BOARD_SIZE[1]:
                if self.board[x][y]!='':
                    return False
                if x == x2 and y == y2:
                    return True
                x, y = x + dx, y + dy
        # check if there is a path in the other directions
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            x, y = x1 + dx, y1 + dy
            while 0 <= x < self.BOARD_SIZE[0] and 0 <= y < self.BOARD_SIZE[1]:
                if self.board[x][y] =='':
                    return self.has_path((x, y), pos2)
                x, y = x + dx, y + dy
        # if we reach here, there is no path
        return False

    def remove_icons(self, pos1, pos2):
        """
        remove the connected icons on the game board
        :param pos1: position tuple(x, y) of the first icon to be removed
        :param pos2: position tuple(x, y) of the second icon to be removed
        :return: None
        """
        # check if the two icons are connected
        if pos1[0] == pos2[0] or pos1[1] == pos2[1] or abs(pos1[0] - pos2[0]) == abs(pos1[1] - pos2[1]):
            # remove all the icons that are connected to the first icon and the second icon
            for i in range(max(pos1[0], pos2[0]), min(pos1[0], pos2[0]) - 1, -1):
                for j in range(max(pos1[1], pos2[1]), min(pos1[1], pos2[1]) - 1, -1):
                    if self.board[i][j] in [self.ICONS[pos1[0]], self.ICONS[pos2[0]]]:
                        self.board[i][j] =''

    def is_game_over(self):
        """
        Check if the game is over (i.e., if there are no more icons on the game board)
        :return: True or False,representing whether the game is over
        """
        for row in self.board:
            for icon in row:
                if icon!='':
                    return False
        return True

